class Solution:
    def countPyramids(self, grid):      
        # dp[i][j] represents the number of layers of the largest pyramid with (i, j) as the vertex.
        # Note that the 1-level pyramid is invalid in the problem, so it should be removed when summing.
        # Note that if grid[i][j] is 0, dp[i][j] will always be 0.
        # The dp recurrence formula is dp[i][j] = min(dp[i + 1][j - 1], dp[i + 1][j + 1]) + 1
        m, n, dp, cnt = len(grid), len(grid[0]), copy.deepcopy(grid), 0
        # triangle
        for i in range(m - 2, -1, -1):
            for j in range(1, n - 1):
                if dp[i][j] > 0 and dp[i + 1][j] > 0:
                    dp[i][j] = min(dp[i + 1][j - 1], dp[i + 1][j + 1]) + 1
                    cnt += dp[i][j] - 1
        # inverted triangle
        dp = grid
        for i in range(1, m):
            for j in range(1, n - 1):
                if dp[i][j] > 0 and dp[i - 1][j] > 0:
                    dp[i][j] = min(dp[i - 1][j - 1], dp[i - 1][j + 1]) + 1
                    cnt += dp[i][j] - 1
        return cnt

class Solution:
    def countPyramids(self, grid):
        def count(grid):
            dp = [[0 for _ in range(len(grid[0]))] for _ in range(len(grid))]
            for i in range(1, len(grid)):
                for j in range(1, len(grid[0])-1):
                    if grid[i][j] == grid[i-1][j-1] == grid[i-1][j] == grid[i-1][j+1] == 1:
                        dp[i][j] = min(dp[i-1][j-1], dp[i-1][j], dp[i-1][j+1])+1
            return sum(sum(row) for row in dp)

        return count(grid) + count(grid[::-1])

class Solution:
    def countPyramids(self, grid):
        def count(grid, reverse):
            def get_grid(i, j):
                return grid[~i][j] if reverse else grid[i][j]

            result = 0
            dp = [0]*len(grid[0])
            for i in range(1, len(grid)):
                new_dp = [0]*len(grid[0])
                for j in range(1, len(grid[0])-1):
                    if get_grid(i, j) == get_grid(i-1, j-1) == get_grid(i-1, j) == get_grid(i-1, j+1) == 1:
                        new_dp[j] = min(dp[j-1], dp[j+1])+1
                dp = new_dp
                result += sum(dp)
            return result

        return count(grid, False) + count(grid, True)

